class Solution:
    def maximumLength(self, s: str) -> int:
        counts = {}
        n = len(s)

        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1

            length = j - i
            char = s[i]

            for l in range(1, length + 1):
                counts[(char, l)] = counts.get((char, l), 0) + (length - l + 1)

            i = j

        ans = -1
        for (_, length), count in counts.items():
            if count >= 3:
                ans = max(ans, length)

        return ans
